// Builds the office email from the intake payload. Pure formatting: no pricing
// decisions happen here — every number arrives already computed server-side.

const p = $json.body || $json;

const money = (n) => '$' + Number(n || 0).toLocaleString('en-US');
const esc = (s) => String(s == null ? '' : s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;');

const customer = p.customer || {};
const plan = p.plan || {};
const totals = p.totals || {};
const addons = Array.isArray(p.addons) ? p.addons : [];

// Local (Mountain) time for the office, with a clear fallback.
let submittedLocal = p.submittedAt || '';
try {
  submittedLocal = new Date(p.submittedAt).toLocaleString('en-US', {
    timeZone: 'America/Denver',
    dateStyle: 'medium',
    timeStyle: 'short'
  }) + ' MT';
} catch (e) { /* keep the raw ISO string */ }

const addonRows = addons.map((a) => {
  const qty = Number(a.quantity) || 1;
  const qtyLabel = qty > 1 ? ' &times; ' + qty : '';
  let amount;
  if (a.includedFree) amount = 'Included with plan';
  else if (a.locked) amount = 'Not charged &mdash; not covered by the selected plan';
  else amount = money(a.lineTotal);
  const unit = (!a.includedFree && !a.locked && qty > 1) ? ' <span style="color:#6b6b73">(' + money(a.unitPrice) + ' each)</span>' : '';
  return '<tr>'
    + '<td style="padding:6px 12px 6px 0;border-bottom:1px solid #e8e8ec">' + esc(a.name) + qtyLabel + unit + '</td>'
    + '<td style="padding:6px 0;border-bottom:1px solid #e8e8ec;text-align:right;white-space:nowrap">' + amount + '</td>'
    + '</tr>';
}).join('');

const addonSection = addons.length
  ? addonRows
  : '<tr><td colspan="2" style="padding:6px 0;color:#6b6b73;border-bottom:1px solid #e8e8ec">No add-ons selected</td></tr>';

const dashboardLink = p.dashboardUrl
  ? '<p style="margin:20px 0 0"><a href="' + esc(p.dashboardUrl) + '" style="background:#7b1f2b;color:#fff;padding:10px 18px;border-radius:6px;text-decoration:none;display:inline-block">Open the Submissions Dashboard</a></p>'
  : '';

const subject = 'New Care Plan request: ' + (plan.name || 'Care Plan') + ' - ' + (customer.name || 'Unknown customer');

const html = '<div style="font-family:Segoe UI,Arial,sans-serif;font-size:14px;color:#26262a;line-height:1.5">'
  + '<h2 style="margin:0 0 4px;font-size:18px">New Care Plan request</h2>'
  + '<p style="margin:0 0 18px;color:#6b6b73">Submission ' + esc(p.submissionNumber) + ' &middot; ' + esc(submittedLocal) + '</p>'
  + '<table style="border-collapse:collapse;margin:0 0 18px">'
  + '<tr><td style="padding:4px 16px 4px 0;color:#6b6b73">Customer</td><td style="padding:4px 0"><strong>' + esc(customer.name) + '</strong></td></tr>'
  + '<tr><td style="padding:4px 16px 4px 0;color:#6b6b73">Phone</td><td style="padding:4px 0"><a href="tel:' + esc(String(customer.phone || '').replace(/[^\d+]/g, '')) + '">' + esc(customer.phone) + '</a></td></tr>'
  + '<tr><td style="padding:4px 16px 4px 0;color:#6b6b73">Address</td><td style="padding:4px 0">' + esc(customer.address) + '</td></tr>'
  + '<tr><td style="padding:4px 16px 4px 0;color:#6b6b73">Best time to call</td><td style="padding:4px 0">' + esc(customer.bestTime) + '</td></tr>'
  + '</table>'
  + '<table style="border-collapse:collapse;min-width:420px">'
  + '<tr><td style="padding:6px 12px 6px 0;border-bottom:2px solid #26262a"><strong>' + esc(plan.name) + '</strong> (base)</td>'
  + '<td style="padding:6px 0;border-bottom:2px solid #26262a;text-align:right">' + money(plan.basePrice) + '</td></tr>'
  + addonSection
  + '<tr><td style="padding:8px 12px 8px 0"><strong>Annual total</strong></td>'
  + '<td style="padding:8px 0;text-align:right"><strong>' + money(totals.total) + '/yr</strong></td></tr>'
  + '</table>'
  + '<p style="margin:14px 0 0;color:#6b6b73;font-size:13px">Add-ons subtotal ' + money(totals.addonTotal) + ' &middot; about ' + money(totals.monthlyEquivalent) + '/mo equivalent. Billed annually; monthly payments are not offered.</p>'
  + '<p style="margin:14px 0 0;color:#6b6b73;font-size:13px">This is a request, not an enrolment: no payment was taken and the plan is not active. Call the customer during office hours to confirm plan, price and terms.</p>'
  + dashboardLink
  + '</div>';

return { json: { subject, html, to: 'service@suncitylc.com', submissionNumber: p.submissionNumber, submissionId: p.submissionId } };
